<?php get_header(); ?>
<main id="content"><section class="saf-page-hero saf-catalog-hero"><div class="saf-container"><span class="saf-kicker">ОПТОВИЙ КАТАЛОГ</span><h1>Квіти для професійних покупців</h1><p>Використовуйте пошук і категорії, щоб швидко знайти потрібний тип квітів. Актуальну наявність і комерційні умови підтверджуємо за запитом.</p></div></section>
<section class="saf-section saf-catalog-section"><div class="saf-container"><div class="saf-catalog-tools"><label class="saf-search"><span>Пошук</span><input type="search" id="saf-catalog-search" placeholder="Наприклад: троянда, тюльпан..." autocomplete="off"></label><div class="saf-filter-buttons"><button type="button" class="is-active" data-filter="all">Усі</button><?php $terms=get_terms(['taxonomy'=>'flower_category','hide_empty'=>false]); if(!is_wp_error($terms)) foreach($terms as $term) echo '<button type="button" data-filter="'.esc_attr($term->slug).'">'.esc_html($term->name).'</button>'; ?></div></div>
<div class="saf-product-grid" id="saf-catalog-grid"><?php if(have_posts()): while(have_posts()): the_post(); $terms=get_the_terms(get_the_ID(),'flower_category'); $slugs=[]; if($terms&&!is_wp_error($terms)) foreach($terms as $t)$slugs[]=$t->slug; ?><article class="saf-product-card" data-title="<?php echo esc_attr(mb_strtolower(get_the_title().' '.get_the_excerpt())); ?>" data-categories="<?php echo esc_attr(implode(' ',$slugs)); ?>"><a class="saf-product-image" href="<?php the_permalink(); ?>"><img src="<?php echo esc_url(saftrade_flower_image_url(get_the_ID())); ?>" data-saf-fallback="<?php echo esc_url(saftrade_flower_placeholder_image(get_the_ID())); ?>" alt="<?php echo esc_attr(get_the_title()); ?>" loading="lazy"></a><div class="saf-product-body"><div class="saf-product-tax"><?php echo ($terms&&!is_wp_error($terms))?esc_html($terms[0]->name):'Квіти'; ?></div><h2><a href="<?php the_permalink(); ?>"><?php the_title(); ?></a></h2><p><?php echo esc_html(wp_trim_words(get_the_excerpt(),20)); ?></p><div class="saf-product-meta"><span><?php echo esc_html(get_post_meta(get_the_ID(),'saf_origin',true) ?: 'Походження — уточнюється для партії'); ?></span><span><?php echo esc_html(get_post_meta(get_the_ID(),'saf_availability',true) ?: 'Наявність — за запитом'); ?></span></div><a class="saf-text-link" href="<?php the_permalink(); ?>">Детальніше <span>→</span></a></div></article><?php endwhile; else: ?><div class="saf-empty"><h2>Не знайшли потрібну позицію?</h2><p>Онлайн-каталог показує частину напрямків асортименту. Надішліть B2B-запит — потрібну категорію та актуальну доступність можна уточнити окремо.</p><button class="saf-btn" type="button" data-saf-quote>Запросити асортимент</button></div><?php endif; ?></div><div class="saf-no-results" hidden>Нічого не знайдено. Спробуйте інший запит або відкрийте всі категорії.</div><?php the_posts_pagination(); ?></div></section></main>
